/* 
	Lava Triangles
	https://openprocessing.org/sketch/2142993
	#genuary12 #genuary #creativecoding #generativeart

	https://genuary.art/prompts#jan12
*/

const SZE = 50;
let items, clrs, cs1, cs2;

function setup() {
	createCanvas(windowHeight * 3 / 4, windowHeight);
	describe("triangles floating around in a lava lamp style")
	pixelDensity(1)
	frameRate(30)
	colorMode(HSB, 100);
	clrs = genColors(24, 100);
	cs1 = clrs.splice(0, 6);
	cs2 = clrs.splice(2, 6);
	initItems(random(40, 80));
	background("beige");
}

function initItems(num = 10) {
	items = [];
	for (let i = 0; i < num; i++) {
		const s = random(height * 0.05, height * 0.2)
		const x = random(width * 0.2, width * 0.8);
		const h = random(height * 0.1, height * 0.5);
		const item  = new Triangle(x, h, s, ~~random(4), random(clrs))
		items.push(item)
	}
}

function draw() {
	background("beige");
	// background("rgba(245,245,220,0.04)");

	// drawPre()

	// triangles
	for (let i of items) {
		i.update(random() < 0.001)
		i.show();
	}

	// shadow in front
	translate(SZE * 0.4, -SZE * 0.4);
	for (let i of items) {
		const n = map(noise(frameCount * 0.01 + i.x + i.y), 0, 1, 0.5, 0.9);
		// i.show(color(`rgba(0, 0, 0, ${n})`));
	}
}

function drawPre(back = false) {
	// pre
	if (back) {
		push()
		for (let i = 0; i < width + height; i += 10) {
			drawingContext.setLineDash([~~(10+i%10)]);
			var n = noise(frameCount * 0.0013 + i)
			stroke(`rgba(255,255,255,${n})`)
			line(0, i, i, 0);
		}
		pop()
	}

	if (true) {
		noStroke();
		const ctx = drawingContext;
		// outer / background
		const gradOuter = ctx.createLinearGradient(0, 0, width, height);
		gradOuter.addColorStop(0, cs1[2]);
		gradOuter.addColorStop(1, cs1[4]);
		ctx.fillStyle = gradOuter;
		rect(0, 0, width, height);
		// inner / form
		const gradInner = ctx.createLinearGradient(0, 0, 0, height);
		gradInner.addColorStop(0, cs2[2]);
		gradInner.addColorStop(1, cs2[4]);
		ctx.fillStyle = gradOuter;
		beginShape();
		vertex(width * 0.3, height * 0.1);
		vertex(width * 0.7, height * 0.1);
		vertex(width * 0.95, height * 0.4);
		vertex(width * 0.9, height * 0.95);
		vertex(width * 0.1, height * 0.95);
		vertex(width * 0.05, height * 0.4);
		endShape(CLOSE)

		fill("rgb(104,88,4)")
		rect(width * 0.1, height * 0.95, width * 0.8, height * 0.05)
	}
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function genColors(n = 2, space = 100) {
	arr = [];
	const HUE = ~~random(100);
	const DLT = space / n;
	for (let i = 0; i < n; i++) {
		const clr = color((HUE + i * DLT) % 100, random(25, 50), random(35, 65), 50);
		arr.push(clr);
	}
	return arr;
}

class Triangle {
	constructor(x, h, s, rot, clr) {
		this.s = s;

		this.cx = x;
		this.cy = height -s*0.5 -h*0.5;

		this.amp = h;
		this.rot = rot;
		this.da = random(0.005, 0.035) * ((random() < 0.5) ? 1 : -1);
		this.ang = random(TWO_PI)
		this.clr = clr;

		this.x = x;
		this.y = h; 
		this.calcProps()
	}

	calcProps() {
		this.x = this.cx + sin(this.ang) * this.amp * 0.3;
    this.y = this.cy + cos(this.ang) * this.amp;
    this.x = lerp(this.x, width * 0.5, map(abs(height * 3 / 4 - this.y), 0, height, 0.2, 0.6));
	}

	update(rot = false) {
		if (rot) {
			this.rot = (this.rot + 1) % 4;
		}
		this.ang += this.da;
		this.calcProps();
	}

	show(_clr) {
		var clr = _clr || this.clr;
		push();
		noStroke();
		fill(clr);

		const s_2 = this.s * 0.5;
		translate(this.x, this.y);
		rotate(this.rot * HALF_PI)
		rotate(sin(this.ang) * 0.1)
		//translate(-s_2, -s_2)
		//triangle(0, 0, 0, this.s, this.s, this.s)
		triangle(-s_2, -s_2, -s_2, s_2, s_2, s_2)

		pop();		
	}
}
